}));
const EmptyDocIcon = () => React.createElement('svg', {
  width: 36,
  height: 36,
  viewBox: '0 0 24 24',
  fill: 'none',
  stroke: 'currentColor',
  strokeWidth: 1.5,
  strokeLinecap: 'round',
  strokeLinejoin: 'round'
}, React.createElement('path', {
  d: 'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z'
}), React.createElement('polyline', {
  points: '14 2 14 8 20 8'
}), React.createElement('line', {
  x1: 12,
  y1: 12,
  x2: 12,
  y2: 18
}), React.createElement('line', {
  x1: 9,
  y1: 15,
  x2: 15,
  y2: 15
}));
const SortIcon = React.memo(({
  col,
  sortKey,
  sortDir
}) => {
  const isActive = sortKey === col;
  return React.createElement('span', {
    className: 'cm-th-sort-icon ' + (isActive ? 'active' : '')
  }, isActive ? sortDir === 'asc' ? '▲' : '▼' : '⇅');
});

// ============================================================================
// HELPERS
// ============================================================================
const useDebounce = (value, delay) => {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const t = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(t);
  }, [value, delay]);
  return debounced;
};
const parseAppsmithModel = modelRaw => {
  if (!modelRaw) return {};
  let parsed = modelRaw;
  if (typeof modelRaw === 'string') {
    try {
      parsed = JSON.parse(modelRaw);
    } catch (e) {}
  }
  return parsed || {};
};

// ============================================================================
// CELL RENDERER (Type-Driven Render Engine)
// ============================================================================
const CellRenderer = ({
  value,
  type,
  align
}) => {
  if (value === undefined || value === null) return null;
  const style = align ? {
    textAlign: align
  } : {};
  switch (type) {
    case 'text':
      return React.createElement('div', {
        style
      }, String(value));
    case 'number':
      // Numbers often look best with tabular lining figures or right alignment
      return React.createElement('div', {
        style: {
          ...style,
          fontVariantNumeric: 'tabular-nums'
        }
      }, String(value));
    case 'date':
      // Renders standard dates. Note: We use the time-cell class from the original design for consistent padding
      return React.createElement('div', {
        className: 'cm-time-cell',
        style
      }, React.createElement('span', {
        className: 'cm-time-date'
      }, String(value)));
    case 'badge':
      // Expects { text: string, class: string }
      return React.createElement('div', {
        className: 'cm-status-cell',
        style
      }, React.createElement('span', {
        className: `cm-status-badge ${value.class}`
      }, value.text));
    case 'multi_text':
      // Takes an array of strings or styled objects: { text: '...', color: '#fff', bold: true }
      if (!Array.isArray(value)) return React.createElement('div', {
        style
      }, String(value));
      return React.createElement('div', {
        className: 'cm-pr-cell',
        style
      }, value.map((item, idx) => {
        if (!item) return null;

        // If it's just a string
        if (typeof item === 'string') {
          return React.createElement('div', {
            key: idx,
            className: 'cm-item-name',
            style: {
              marginBottom: '2px'
            }
          }, item);
        }

        // If it's a styled object passed from Appsmith
        const itemStyle = {
          color: item.color || 'inherit',
          fontWeight: item.bold ? 600 : 'normal',
          fontSize: item.size || 'inherit',
          marginBottom: '2px'
        };
        return React.createElement('div', {
          key: idx,
          style: itemStyle
        }, String(item.text || ''));
      }));
    default:
      return React.createElement('div', {
        style
      }, String(value));
  }
};

// ============================================================================
// ERROR BOUNDARY
// ============================================================================
class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      hasError: false,
      error: null
    };
  }
  static getDerivedStateFromError(error) {
    return {
      hasError: true,
      error
    };
  }
  render() {
    if (this.state.hasError) {
      return React.createElement('div', {
        style: {
          padding: '20px',
          color: 'red',
          fontWeight: 'bold'
        }
      }, "Widget Crashed: " + this.state.error.message);
    }
    return this.props.children;
  }
}

// ============================================================================
// MAIN COMPONENT: Universal Schema-Driven Table
// ============================================================================
function UniversalTableWidget() {
  const [modelData, setModelData] = useState(() => parseAppsmithModel(window.appsmith?.model));

  // Destructure dynamic schema and data
  const columns = modelData.columns || [];
  const tableData = modelData.data || [];
  const config = modelData.config || {};

  // Appsmith config parameters with safe fallbacks
  const isSearchable = config.isSearchable ?? false;
  const isFilterable = config.isFilterable ?? false;
  const defaultRowsPerPage = config.defaultRowsPerPage || 10;
  const headerBanner = config.headerBanner || null;
  const filterOptions = config.filterOptions || [];
  const [search, setSearch] = useState('');
  const debouncedSearch = useDebounce(search, 200);
  const [filterValue, setFilterValue] = useState('All');
  const [sortKey, setSortKey] = useState(null);
  const [sortDir, setSortDir] = useState('asc');
  const [page, setPage] = useState(1);
  const [rowsPerPage, setRowsPerPage] = useState(defaultRowsPerPage);

  // Sync rowsPerPage if default changes
  useEffect(() => {
    if (config.defaultRowsPerPage && rowsPerPage !== config.defaultRowsPerPage) {
      setRowsPerPage(config.defaultRowsPerPage);
    }
  }, [config.defaultRowsPerPage]);

  // Listen to AppSmith live model changes
  useEffect(() => {
    if (window.appsmith?.onModelChange) {
      window.appsmith.onModelChange(m => {
        if (!m) return;
        setModelData(parseAppsmithModel(m));
      });
    }
  }, []);

  // Compute which columns are enabled for search
  const searchableColumnIds = useMemo(() => {
    return columns.filter(c => c.searchable).map(c => c.id);
  }, [columns]);

  // 1. Dynamic Column-Based Filtering & Searching
  const filtered = useMemo(() => tableData.filter(row => {
    const q = debouncedSearch.toLowerCase();

    // Search Engine: Iterates only through columns marked as searchable: true
    if (isSearchable && q) {
      let rowText = '';
      searchableColumnIds.forEach(id => {
        const val = row[id];
        if (val) {
          if (typeof val === 'string' || typeof val === 'number') {
            rowText += ' ' + val;
          } else if (Array.isArray(val)) {
            rowText += ' ' + val.join(' ');
          } else if (typeof val === 'object') {
            // Naive extraction for objects like {text: 'P', class: 'c'}
            rowText += ' ' + Object.values(val).join(' ');
          }
        }
      });
      if (!rowText.toLowerCase().includes(q)) return false;
    }

    // External Dropdown Filter logic
    if (isFilterable && filterValue !== 'All') {
      if (row._filterValue !== filterValue) return false;
    }
    return true;
  }), [tableData, debouncedSearch, filterValue, isSearchable, isFilterable, searchableColumnIds]);

  // 2. Type-Driven Smart Sorting
  const sorted = useMemo(() => [...filtered].sort((a, b) => {
    if (!sortKey) return 0;
    const colDef = columns.find(c => c.id === sortKey);
    if (!colDef || !colDef.sortable) return 0;
    let va = a[sortKey];
    let vb = b[sortKey];
    let typeA = colDef.type;
    let typeB = colDef.type;

    // Step 1: If it's a multi_text array, find the specific item they want to sort by
    // The user adds `type: 'number'` (or 'date') to the specific text object they want to sort by.
    if (Array.isArray(va)) {
      const sortTargetA = va.find(v => typeof v === 'object' && v !== null && v.type);
      if (sortTargetA) {
        va = sortTargetA.text;
        typeA = sortTargetA.type;
      } else {
        va = va[0]; // fallback
