}

.cm-skeleton-bar.w20 {
	width: 20%;
}

.cm-skeleton-bar.w25 {
	width: 25%;
}

.cm-skeleton-bar.w15 {
	width: 15%;
}

.cm-skeleton-bar.w10 {
	width: 10%;
}

.cm-skeleton-bar.h10 {
	height: 10px;
	margin-top: 6px;
}

.cm-empty-state {
	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: center;
	padding: 60px 24px;
	gap: 16px;
}

.cm-empty-icon {
	width: 72px;
	height: 72px;
	border-radius: 50%;
	background: #F3F4F6;
	display: flex;
	align-items: center;
	justify-content: center;
}

.cm-empty-icon svg {
	color: #9CA3AF;
}

.cm-empty-title {
	font-size: 16px;
	font-weight: 700;
	color: #6B7280;
	text-align: center;
}

.cm-empty-desc {
	font-size: 13px;
	color: #9CA3AF;
	text-align: center;
	max-width: 360px;
}

/* ============================================================================
LOCKED WORKFLOW BANNER
============================================================================ */
.cm-locked-banner-container {
	display: flex;
	align-items: center;
	gap: 16px;
	padding: 20px 24px;
	background-color: #EFF6FF;
	border: 1px solid #BFDBFE;
