// ============================================================================
// HELPERS
// ============================================================================
const useDebounce = (value, delay) => {
	const [debounced, setDebounced] = useState(value);
	useEffect(() => {
		const t = setTimeout(() => setDebounced(value), delay);
		return () => clearTimeout(t);
	}, [value, delay]);
	return debounced;
};

const parseAppsmithModel = modelRaw => {
	if (!modelRaw) return {};
	let parsed = modelRaw;
	if (typeof modelRaw === 'string') {
		try { parsed = JSON.parse(modelRaw); } catch (e) {}
	}
	return parsed || {};
};

// ============================================================================
// CELL RENDERER (Type-Driven Render Engine)
// ============================================================================
const CellRenderer = ({ value, type, align }) => {
	if (value === undefined || value === null) return null;

	const style = align ? { textAlign: align } : {};

	switch (type) {
		case 'text':
			return React.createElement('div', { style }, String(value));

		case 'number':
			// Numbers often look best with tabular lining figures or right alignment
			return React.createElement('div', { style: { ...style, fontVariantNumeric: 'tabular-nums' } }, String(value));

		case 'date':
			// Renders standard dates. Note: We use the time-cell class from the original design for consistent padding
			return React.createElement('div', { className: 'cm-time-cell', style },
																 React.createElement('span', { className: 'cm-time-date' }, String(value))
																);

		case 'badge':
			// Expects { text: string, class: string }
			return React.createElement('div', { className: 'cm-status-cell', style },
																 React.createElement('span', { className: `cm-status-badge ${value.class}` }, value.text)
																);

		case 'multi_text':
			// Takes an array of strings or styled objects: { text: '...', color: '#fff', bold: true }
			if (!Array.isArray(value)) return React.createElement('div', { style }, String(value));
			return React.createElement('div', { className: 'cm-pr-cell', style },
																 value.map((item, idx) => {
				if (!item) return null;

				// If it's just a string
				if (typeof item === 'string') {
					return React.createElement('div', { key: idx, className: 'cm-item-name', style: { marginBottom: '2px' } }, item);
				}

				// If it's a styled object passed from Appsmith
				const itemStyle = {
					color: item.color || 'inherit',
					fontWeight: item.bold ? 600 : 'normal',
					fontSize: item.size || 'inherit',
					marginBottom: '2px'
				};

				return React.createElement('div', { key: idx, style: itemStyle }, String(item.text || ''));
			})
																);

		default:
			return React.createElement('div', { style }, String(value));
	}
};

// ============================================================================
// ERROR BOUNDARY
// ============================================================================
class ErrorBoundary extends React.Component {
	constructor(props) {
		super(props);
		this.state = { hasError: false, error: null };
	}
	static getDerivedStateFromError(error) {
		return { hasError: true, error };
	}
	render() {
		if (this.state.hasError) {
			return React.createElement('div', { style: { padding: '20px', color: 'red', fontWeight: 'bold' } },
																 "Widget Crashed: " + this.state.error.message
																);
		}
		return this.props.children;
	}
}

