		const colDef = columns.find(c => c.id === sortKey);
		if (!colDef || !colDef.sortable) return 0;

		let va = a[sortKey];
		let vb = b[sortKey];

		let typeA = colDef.type;
		let typeB = colDef.type;

		// Step 1: If it's a multi_text array, find the specific item they want to sort by
		// The user adds `type: 'number'` (or 'date') to the specific text object they want to sort by.
		if (Array.isArray(va)) {
			const sortTargetA = va.find(v => typeof v === 'object' && v !== null && v.type);
			if (sortTargetA) {
				va = sortTargetA.text;
				typeA = sortTargetA.type;
			} else {
				va = va[0]; // fallback
			}
		}

		if (Array.isArray(vb)) {
			const sortTargetB = vb.find(v => typeof v === 'object' && v !== null && v.type);
			if (sortTargetB) {
				vb = sortTargetB.text;
				typeB = sortTargetB.type;
			} else {
				vb = vb[0]; // fallback
			}
		}

