		}
	}, []);

	return React.createElement('div', { className: 'cm-widget-container' },

														 // Dynamic Header Banner
														 (headerBanner && headerBanner.show) && React.createElement('div', { className: 'cm-locked-banner-container' },
																																												React.createElement('div', { className: 'cm-locked-icon' }, headerBanner.icon || 'ℹ️'),
																																												React.createElement('div', { className: 'cm-locked-content' },
																																																						React.createElement('h3', { className: 'cm-locked-title' }, headerBanner.title),
																																																						React.createElement('p', { className: 'cm-locked-desc' }, headerBanner.desc)
																																																					 )
																																											 ),

														 React.createElement('div', { className: 'cm-card' },

																								 // Dynamic Title
																								 (config.title || config.subtitle) && React.createElement('div', { className: 'cm-header' },
																																																					React.createElement('div', { className: 'cm-header-left' },
																																																															React.createElement('div', { className: 'cm-icon-wrap' }, React.createElement(ContractDocIcon, null)),
																																																															React.createElement('div', { className: 'cm-title-block' },
																																																																									config.title && React.createElement('h2', { className: 'cm-title' }, config.title),
																																																																									config.subtitle && React.createElement('div', { className: 'cm-subtitle' }, config.subtitle)
																																																																								 )
																																																														 ),
																																																					config.summaryText && React.createElement('div', { className: 'cm-summary-badge' },
																																																																										React.createElement('span', { className: 'cm-badge-dot' }), config.summaryText
																																																																									 )
																																																				 ),

																								 // Dynamic Toolbar
																								 (isSearchable || isFilterable) && React.createElement('div', { className: 'cm-toolbar' },
																																																			 isSearchable && React.createElement('div', { className: 'cm-search-wrap' },
																																																																					 React.createElement('span', { className: 'cm-search-icon' }, React.createElement(SearchIcon, null)),
																																																																					 React.createElement('input', {
		className: 'cm-search',
		placeholder: config.searchPlaceholder || 'Search...',
