			setPage(1);
		}
	})
																																																																					),
																																																			 isFilterable && React.createElement('div', { className: 'cm-filter-group' },
																																																																					 config.filterLabel && React.createElement('span', { className: 'cm-filter-label' }, config.filterLabel),
																																																																					 React.createElement('select', {
		className: 'cm-select',
		value: filterValue,
		onChange: e => {
			setFilterValue(e.target.value);
			setPage(1);
		}
	},
            filterOptions.map(opt => React.createElement('option', { key: opt.value, value: opt.value }, opt.label))
          )
																																																																					)
																																																			),

																								 // Dynamic Table rendering via Schema
																								 totalItems > 0 && React.createElement('div', { className: 'cm-table-wrapper' },
																																											 React.createElement('table', { className: 'cm-table' },
																																																					 React.createElement('thead', null,
																																																															 React.createElement('tr', null,
																																																																									 columns.map(col => React.createElement('th', {
		key: col.id,
		className: col.sortable ? 'cm-th-sortable' : '',
