		onClick: () => handleSort(col.id, col.sortable)
	}, col.label, ' ', col.sortable && React.createElement(SortIcon, { col: col.id, sortKey, sortDir })))
																																																																									)
																																																															),
																																																					 React.createElement('tbody', null, pageRows.map((row, idx) =>
            React.createElement('tr', {
