																																												 React.createElement('div', { className: 'cm-empty-icon' }, React.createElement(EmptyDocIcon, null)),
																																												 React.createElement('div', { className: 'cm-empty-title' }, config.emptyState?.title || 'No Results Found'),
																																												 React.createElement('div', { className: 'cm-empty-desc' }, config.emptyState?.desc || 'Try adjusting your search or filter criteria.')
																																												),

																								 // Dynamic Pagination
																								 totalItems > 0 && React.createElement('div', { className: 'cm-pagination' },
																																											 React.createElement('div', { className: 'cm-page-info' }, `Showing ${showStart}-${showEnd} of ${totalItems} items`),
																																											 React.createElement('div', { className: 'cm-page-controls' },
																																																					 React.createElement('button', {
